module priority_encoder (
    input [3:0] in,
    output reg [1:0] code
);

always @(*) begin
    if (in[3])        code = 2'b11;
    else if (in[2])   code = 2'b10;
    else if (in[1])   code = 2'b01;
    else if (in[0])   code = 2'b00;
    else             code = 2'b00;
end

endmodule

module fsm_3state (
    input clk, reset,
    output [1:0] state
);

localparam S0 = 2'b00;
localparam S1 = 2'b01;
localparam S2 = 2'b10;
localparam S3 = 2'b11;

reg [1:0] current_state, next_state;

// State transition logic
always @(posedge clk) begin
    if (reset)
        current_state <= S0;
    else
        current_state <= next_state;
end

// Next state logic
always @(*) begin
    case (current_state)
        S0: next_state = S1;
        S1: next_state = S2;
        S2: next_state = S3;
        S3: next_state = S0;
        default: next_state = S0; // Handle unexpected states
    endcase
end

// Output current state
assign state = current_state;

endmodule

module traffic_light (
    input clk, reset,
    output [2:0] light
);

reg [1:0] state_reg;
reg [2:0] light_reg;

always @(posedge clk) begin
    if (reset)
        state_reg <= 2'b00;
    else begin
        case (state_reg)
            2'b00: state_reg <= 2'b01; // S0 → S1 (green)
            2'b01: state_reg <= 2'b10; // S1 → S2 (yellow)
            2'b10: state_reg <= 2'b11; // S2 → S3 (red)
            2'b11: state_reg <= 2'b01; // S3 → S1 (red → green)
            default: state_reg <= 2'b00;
        endcase
    end
end

always @(*) begin
    case (state_reg)
        2'b00: light_reg = 3'b010; // Green
        2'b01: light_reg = 3'b110; // Yellow
        2'b10: light_reg = 3'b101; // Red
        2'b11: light_reg = 3'b101; // Red
        default: light_reg = 3'b000;
    endcase
end

assign light = light_reg;

endmodule

module elevator_controller (
    input clk, reset,
    input up_request, down_request,
    output [1:0] state
);

    // State encoding parameters
    localparam [1:0] UP    = 2'b00;
    localparam [1:0] DOWN  = 2'b01;
    localparam [1:0] NEON  = 2'b10;

    reg [1:0] state_reg, next_state;

    // State register with synchronous reset
    always @(posedge clk or posedge reset) begin
        if (reset) state_reg <= UP;
        else       state_reg <= next_state;
    end

    // Next state logic
    always @(*) begin
        case (state_reg)
            UP:    next_state = down_request ? UP   : DOWN;
            DOWN:  next_state = up_request  ? UP   : DOWN;
            NEON:  next_state = (up_request || down_request) ? UP : DOWN;
            default: next_state = UP; // Handle undefined states
        endcase
    end

    // Output current state
    assign state = state_reg;

endmodule

module vending_machine (
    input clk, reset,
    input coin_inserted, item_selected,
    output [1:0] state
);

// State definitions
localparam [1:0] IDLE     = 2'b00,
                 SELECTION = 2'b01,
                 PURCHASE  = 2'b10;

reg [1:0] current_state, next_state;

// Sequential state update with reset
always @(posedge clk or posedge reset) begin
    if (reset) begin
        current_state <= IDLE;
    end else begin
        current_state <= next_state;
    end
end

// Combinational next state logic
always @* begin
    next_state = current_state; // Default to stay in current state
    case (current_state)
        IDLE: begin
            if (coin_inserted)
                next_state = SELECTION;
        end
        SELECTION: begin
            if (item_selected)
                next_state = PURCHASE;
        end
        PURCHASE: begin
            next_state = IDLE;
        end
        default: next_state = IDLE; // Handle undefined states
    endcase
end

// Output current state
assign state = current_state;

endmodule

module bitwise_ops (
    input [7:0] a, b,
    output [7:0] and_out,
    output [7:0] or_out,
    output [7:0] xor_out
);

    assign and_out = a & b;
    assign or_out  = a | b;
    assign xor_out = a ^ b;

endmodule

