module rotate_left (
    input [7:0] in,
    input [2:0] shift,
    output [7:0] out
);

wire [7:0] shifted;

assign shifted = (shift[2]) ? (shift[1] ? (in << 1) : (in << 2)) : (shift[1] ? (in << 2) : (in << 1));
assign out = (shift[0]) ? 8'hFF : shifted;

endmodule

module relu (
    input signed [15:0] in_0,
    output signed [15:0] out);

assign out = in_0[15] ? 16'd0 : {1'b0, in_0[14:0] << 1};

endmodule

module caesar_cipher (
    input [7:0] data_in,
    output [7:0] data_out
);

assign data_out[0] = ~data_in[0];
assign data_out[1] = data_in[1] ^ data_in[0];
assign data_out[2] = (data_in[2] & data_in[1]) ^ (~data_in[0]);
assign data_out[3] = (data_in[3] & (data_in[1] | data_in[0])) ^ (~data_in[2]);
assign data_out[4] = data_in[4] ^ (data_in[3] & (data_in[2] | (~data_in[1] & data_in[0])));
assign data_out[5] = data_in[5] ^ (data_in[4] & (data_in[3] | (data_in[2] & (~data_in[1] | data_in[0]))));
assign data_out[6] = data_in[6] ^ (data_in[5] & (data_in[4] | (data_in[3] & (data_in[2] | (~data_in[1] & data_in[0]))));
assign data_out[7] = data_in[7] ^ (data_in[6] & (data_in[5] | (data_in[4] & (data_in[3] | (data_in[2] & (~data_in[1] | data_in[0]))));

endmodule

module clock_div2 (
    input clk,
    input rst,
    output clk_out
);

reg state;

always @(posedge clk) begin
    if (rst)
        state <= 1'b0;
    else
        state <= ~state;
end

assign clk_out = state;

endmodule

`timescale 1ns/1ps

module comparator_4bit(input [3:0] a, input [3:0] b, output gt, eq, lt);

    wire [3:0] eq_bits = a ~^ b;
    wire [3:0] eq_so_far;

    assign eq_so_far[3] = 1'b1;
    assign eq_so_far[2] = eq_bits[3];
    assign eq_so_far[1] = eq_bits[3] & eq_bits[2];
    assign eq_so_far[0] = eq_bits[3] & eq_bits[2] & eq_bits[1];

    wire [3:0] gt_bits = a & ~b & eq_so_far;
    wire [3:0] lt_bits = ~a & b & eq_so_far;

    assign gt = |gt_bits;
    assign eq = &eq_bits;
    assign lt = |lt_bits;

endmodule

