module gray_counter8(
    input wire clk,
    input wire rst,
    output wire [7:0] count
);

reg [3:0] bin_count;

// Binary counter with reset
always @(posedge clk) begin
    if (rst) begin
        bin_count <= 4'b0;
    end else begin
        bin_count <= bin_count + 1;
    end
end

// Convert binary to Gray code using XOR between adjacent bits
assign count[7] = bin_count[3];
assign count[6] = bin_count[3] ^ bin_count[2];
assign count[5] = bin_count[2] ^ bin_count[1];
assign count[4] = bin_count[1] ^ bin_count[0];
assign count[3] = bin_count[0];
assign count[2] = bin_count[0] ^ bin_count[1];
assign count[1] = bin_count[1] ^ bin_count[2];
assign count[0] = bin_count[2] ^ bin_count[3];

endmodule

module johnson_counter4 (
    input clk,
    input rst,
    output [3:0] q
);

reg [3:0] q_reg;
wire [3:0] d;

assign d[0] = ~q_reg[0];
assign d[1] = q_reg[0];
assign d[2] = q_reg[1];
assign d[3] = q_reg[2];

assign q = q_reg;

always @(posedge clk) begin
    if (rst) begin
        q_reg <= 4'b0000;
    end else begin
        q_reg <= d;
    end
end

endmodule

module piso_8bit(
    input clk,
    input rst,
    input load,
    input [7:0] pin,
    output sout
);

reg [7:0] shift_reg;

always @(posedge clk) begin
    if (rst)
        shift_reg <= 8'b0;
    else if (load)
        shift_reg <= pin;
    else
        shift_reg <= shift_reg << 1;
end

assign sout = shift_reg[7];

endmodule

module priority_encoder_4to2 (
    input  [3:0] in,
    output [1:0] out,
    output       valid
);

    assign valid = |in;
    assign out[1] = in[3] | in[2];
    assign out[0] = in[3] | (in[1] & ~in[2]);

endmodule

module ring_counter4 (
    input clk,
    input rst,
    output [3:0] q
);

reg [3:0] q_reg;

assign q = q_reg;

always @(posedge clk) begin
    if (rst) begin
        q_reg <= 4'b0001;
    end else begin
        q_reg <= (q_reg << 1) | (q_reg >> 3);
    end
end

endmodule

