module TopModule (
  input clk,
  input resetn,
  input  [2:0] r,
  output [2:0] g
);

// Define states
localparam [1:0] IDLE = 2'b00,
                 GNT1 = 2'b01,
                 GNT2 = 2'b10,
                 GNT3 = 2'b11;

reg [1:0] current_state, next_state;

// Next state logic
always @* begin
  case (current_state)
    IDLE: begin
      if (r[0])
        next_state = GNT1;
      else if (r[1])
        next_state = GNT2;
      else if (r[2])
        next_state = GNT3;
      else
        next_state = IDLE;
    end
    GNT1: next_state = r[0] ? GNT1 : IDLE;
    GNT2: next_state = r[1] ? GNT2 : IDLE;
    GNT3: next_state = r[2] ? GNT3 : IDLE;
    default: next_state = IDLE;
  endcase
end

// State register with synchronous reset
always @(posedge clk) begin
  if (!resetn)
    current_state <= IDLE;
  else
    current_state <= next_state;
end

// Output logic
assign g[0] = (current_state == GNT1);
assign g[1] = (current_state == GNT2);
assign g[2] = (current_state == GNT3);

endmodule

module TopModule (
  input clk,
  input w,
  input R,
  input E,
  input L,
  output reg Q
);

always @(posedge clk) begin
  if (E || L)
    Q <= R;
  else if (L)
    Q <= w;
  // When E and L are both 0, Q retains its value
end

endmodule

module TopModule (
  input p1a,
  input p1b,
  input p1c,
  input p1d,
  input p1e,
  input p1f,
  output p1y,
  input p2a,
  input p2b,
  input p2c,
  input p2d,
  output p2y
);

  wire int1 = (p1a & p1b) | (p1c & (p1d | p1e | p1f));
  wire int2 = (p2a & p2b) | (p2c & p2d);
  assign p1y = int1;
  assign p2y = int2;

endmodule

module TopModule (
  input a,
  input b,
  output out_assign,
  output reg out_alwaysblock
);

  wire temp;
  assign temp = a & b;
  assign out_assign = temp;

  always @(*) begin
    out_alwaysblock = temp;
  end

endmodule

module TopModule (
  input clk,
  input a,
  input b,
  output out_assign,
  output reg out_always_comb,
  output reg out_always_ff
);

  // Combinational logic for out_assign and out_always_comb
  assign out_assign = a ^ b;
  always @(*) begin
    out_always_comb = a ^ b;
  end

  // Register out_always_ff on clock edge
  always @(posedge clk) begin
    out_always_ff <= a ^ b;
  end

endmodule

module TopModule (
  input a,
  input b,
  input sel_b1,
  input sel_b2,
  output out_assign,
  output reg out_always
);

  wire mux_out;

  // Multiplexer logic: selects a when sel_b1 and sel_b2 are both 1, else b
  assign mux_out = (sel_b1 & sel_b2) ? a : b;

  // Assign outputs
  assign out_assign = mux_out;

  // Register b for simulation (updates to mux_out)
  always @(*) begin
    out_always = mux_out;
  end

endmodule

module TopModule (
  input cpu_overheated,
  output reg shut_off_computer,
  input arrived,
  input gas_tank_empty,
  output reg keep_driving
);

  reg [1:0] state;
  reg [1:0] next_state;

  localparam IDLE = 2'b00;
  localparam STOP = 2'b01;
  localparam EVAC = 2'b10;

  // State transition logic
  always @* begin
    case (state)
      IDLE: next_state = (cpu_overheated || gas_tank_empty || arrived) ? STOP : IDLE;
      STOP: next_state = (cpu_overheated || gas_tank_empty || arrived) ? EVAC : STOP;
      EVAC: next_state = (cpu_overheated || gas_tank_empty || arrived) ? EVAC : IDLE;
      default: next_state = IDLE;
    endcase
  end

  // Output logic for shut_off_computer
  always @* begin
    shut_off_computer = cpu_overheated;
  end

  // Output logic for keep_driving
  always @* begin
    case (state)
      IDLE, STOP: keep_driving = !(cpu_overheated || gas_tank_empty || arrived);
      EVAC: keep_driving = 1'b0;
      default: keep_driving = 1'b0;
    endcase
  end

  // State register update
  always @(posedge clk or posedge reset) begin
    if (reset) begin
      state <= IDLE;
    end else begin
      state <= next_state;
    end
  end

endmodule

