module TopModule (
  input [7:0] code,
  output reg [3:0] out,
  output reg valid
);

  always @* begin
    case (code)
      8'h30: begin // '0'
        out = 4'd0;
        valid = 1'b1;
      end
      8'h31: begin // '1'
        out = 4'd1;
        valid = 1'b1;
      end
      8'h32: begin // '2'
        out = 4'd2;
        valid = 1'b1;
      end
      8'h33: begin // '3'
        out = 4'd3;
        valid = 1'b1;
      end
      8'h34: begin // '4'
        out = 4'd4;
        valid = 1'b1;
      end
      8'h35: begin // '5'
        out = 4'd5;
        valid = 1'b1;
      end
      8'h36: begin // '6'
        out = 4'd6;
        valid = 1'b1;
      end
      8'h37: begin // '7'
        out = 4'd7;
        valid = 1'b1;
      end
      8'h38: begin // '8'
        out = 4'd8;
        valid = 1'b1;
      end
      8'h39: begin // '9'
        out = 4'd9;
        valid = 1'b1;
      end
      default: begin
        out = 4'bxxxx;
        valid = 1'b0;
      end
    endcase
  end

endmodule

