module TopModule (
  input clk,
  input reset,
  output reg [3:0] q
);

  always @(posedge clk) begin
    if (reset) begin
      q <= 4'd9;
    end else if (q == 4'd0) begin
      q <= 4'd9;
    end else begin
      q <= q - 4'd1;
    end
  end

endmodule

module TopModule (
  input clk,
  input areset,
  input train_valid,
  input train_taken,
  output logic [1:0] state
);

  // State encoding parameters
  localparam [1:0] IDLE    = 2'b00,
                   STATE_1 = 2'b01,
                   STATE_2 = 2'b10,
                   STATE_3 = 2'b11;

  // State register
  reg [1:0] current_state, next_state;

  // Sequential state update
  always @(posedge clk or posedge areset) begin
    if (areset)
      current_state <= IDLE;
    else
      current_state <= next_state;
  end

  // Combinational next state logic
  always @(*) begin
    next_state = current_state;  // Default: stay in current state
    if (train_valid && train_taken) begin
      case (current_state)
        IDLE:    next_state = STATE_1;
        STATE_1: next_state = STATE_2;
        STATE_2: next_state = STATE_3;
        STATE_3: next_state = STATE_3;
        default: next_state = IDLE;
      endcase
    end
  end

  // Output assignment
  assign state = current_state;

endmodule

module TopModule (
  input clk,
  input d,
  output reg q
);

  reg [31:0] pc;
  reg [31:0] instr;

  wire [31:0] next_pc = pc + 4;

  always @(posedge clk) begin
    pc <= next_pc;
  end

  always @(posedge clk) begin
    instr <= (next_pc[31:2]) << 2;
  end

  always @* begin
    q = instr[next_pc[2]];
  end

endmodule

