module TopModule (
  input clk,
  input enable,
  input S,
  input A,
  input B,
  input C,
  output reg Z
);

  reg [7:0] buffer;

  always @(posedge clk) begin
    if (enable) begin
      // Load new bit into the buffer
      buffer <= {buffer[6:0], S};
    end
  end

  // Combinational logic for output selection
  always @(*) begin
    if (A)
      Z = buffer[0];
    else if (B)
      Z = buffer[1];
    else if (C)
      Z = buffer[2];
    else
      Z = buffer[3];
  end

endmodule

