  reg [1:0] current_state, next_state;
  reg done_reg;

  always @(posedge clk) begin
    if (reset) begin
      current_state <= S0;
      done_reg <= 1'b0;
    end else begin
      current_state <= next_state;
      done_reg <= (next_state == S3) ? 1'b1 : done_reg;
    end
  end

  always @(*) begin
    case (current_state)
      S0: next_state = (in[3] == 1'b0) ? S1 : S0;
      S1: next_state = (in[3] == 1'b1) ? S2 : S1;
      S2: next_state = (in[3] == 1'b0) ? S3 : S2;
      S3: next_state = S3;
      default: next_state = S0;
    endcase
  end

  assign done = done_reg;

endmodule

module TopModule (
  input clk,
  input in,
  input reset,
  output done
);

  // State definitions
  localparam [1:0] IDLE = 2'b00;
  localparam [1:0] RUN  = 2'b01;
  localparam [1:0] WAIT = 2'b10;

  reg [1:0] current_state, next_state;
  reg [2:0] count; // 3-bit counter (max count 4)
  reg done_reg;

  // State transition logic
  always @(*) begin
    case (current_state)
      IDLE: next_state = in ? RUN : IDLE;
      RUN:  next_state = in ? WAIT : RUN;
      WAIT: next_state = (count == 3'd4) ? IDLE : WAIT;
      default: next_state = IDLE;
    endcase
  end

  // State register
  always @(posedge clk) begin
    if (reset) begin
      current_state <= IDLE;
    end else begin
      current_state <= next_state;
    end
  end

  // Counter logic
  always @(posedge clk) begin
    if (reset) begin
      count <= 3'b0;
    end else begin
      if (current_state == WAIT) begin
        if (count < 3'd4) begin
          count <= count + 1;
        end else begin
          count <= 3'd4;
        end
      end else begin
        count <= 3'b0;
      end
    end
  end

  // Done signal generation
  always @(posedge clk) begin
    if (reset) begin
      done_reg <= 1'b0;
    end else begin
      if (current_state == WAIT && count == 3'd4) begin
        done_reg <= 1'b1;
      end else begin
        done_reg <= 1'b0;
      end
    end
  end

  assign done = done_reg;

endmodule

