module TopModule (
  input clk,
  input areset,
  input bump_left,
  input bump_right,
  output walk_left,
  output walk_right
);

  localparam LEFT = 1'b0;
  localparam RIGHT = 1'b1;

  reg state;

  always @(posedge clk or posedge areset) begin
    if (areset) begin
      state <= LEFT;
    end else begin
      case (state)
        LEFT: state <= (bump_left) ? RIGHT : LEFT;
        RIGHT: state <= (bump_right) ? LEFT : RIGHT;
        default: state <= LEFT;
      endcase
    end
  end

  assign walk_left = (state == LEFT);
  assign walk_right = (state == RIGHT);

endmodule

module TopModule (
  input clk,
  input areset,
  input bump_left,
  input bump_right,
  input ground,
  output walk_left,
  output walk_right,
  output aaah
);

  parameter IDLE = 2'b00;
  parameter WALK_RIGHT = 2'b01;
  parameter WALK_LEFT = 2'b10;
  parameter STOP = 2'b11;

  reg [1:0] current_state, next_state;

  always @(posedge clk or posedge areset) begin
    if (areset)
      current_state <= IDLE;
    else
      current_state <= next_state;
  end

  always @(*) begin
    case (current_state)
      IDLE: begin
        if (ground) begin
          if (bump_left)
            next_state = WALK_RIGHT;
          else if (bump_right)
            next_state = WALK_LEFT;
          else
            next_state = STOP;
        end else
          next_state = IDLE;
      end
      WALK_RIGHT: begin
        if (ground && bump_left)
          next_state = WALK_RIGHT;
        else
          next_state = IDLE;
      end
      WALK_LEFT: begin
        if (ground && bump_right)
          next_state = WALK_LEFT;
        else
          next_state = IDLE;
      end
      STOP: begin
        if (ground)
          next_state = STOP;
        else
          next_state = IDLE;
      end
      default: next_state = IDLE;
    endcase
  end

  assign walk_right = (current_state == WALK_RIGHT);
  assign walk_left = (current_state == WALK_LEFT);
  assign aaah = (current_state == STOP) || (current_state == WALK_RIGHT && bump_left) 
               || (current_state == WALK_LEFT && bump_right);

endmodule

