  input reset,
  input data,
  output start_shifting
);

  reg [2:0] shift_reg;
  reg start_shifting_reg;

  always @(posedge clk) begin
    if (reset) begin
      shift_reg <= 3'b000;
      start_shifting_reg <= 1'b0;
    end else begin
      // Update shift register with new data input
      shift_reg <= {shift_reg[1:0], data};

      // Check if all three bits are 1s or 0s
      if (shift_reg == 3'b111 || shift_reg == 3'b000) begin
        start_shifting_reg <= 1'b1;
      end else begin
        start_shifting_reg <= start_shifting_reg;
      end
    end
  end

  assign start_shifting = start_shifting_reg;

endmodule

