module TopModule (
  input clk,
  input resetn,
  input x,
  input y,
  output f,
  output g
);

  // Define 8 states
  parameter [2:0] s0 = 3'd0,
                  s1 = 3'd1,
                  s2 = 3'd2,
                  s3 = 3'd3,
                  s4 = 3'd4,
                  s5 = 3'd5,
                  s6 = 3'd6,
                  s7 = 3'd7;

  reg [2:0] current_state, next_state;

  // State transition and reset logic
  always @(posedge clk) begin
    if (!resetn)
      current_state <= s0;
    else
      current_state <= next_state;
  end

  // Next state logic based on current state and x/y inputs
  always @(*) begin
    case (current_state)
      s0: next_state = x ? s1 : s0;
      s1: next_state = y ? s2 : s1;
      s2: next_state = x ? s3 : s2;
      s3: next_state = y ? s4 : s3;
      s4: next_state = x ? s5 : s4;
      s5: next_state = y ? s6 : s5;
      s6: next_state = x ? s7 : s6;
      s7: next_state = y ? s0 : s7;
      default: next_state = s0;
    endcase
  end

  // Output logic
  assign f = (current_state == s7);
  assign g = (current_state == s6);

endmodule

