  reg [1:0] current_state, next_state;

  always @(*) begin
    case (current_state)
      S0: begin
        if (x)
          next_state = S1;
        else
          next_state = S2;
      end
      S1: begin
        if (x)
          next_state = S2;
        else
          next_state = S0;
      end
      S2: begin
        if (x)
          next_state = S0;
        else
          next_state = S1;
      end
      default: next_state = S0;
    endcase
  end

  always @(posedge clk) begin
    current_state <= next_state;
  end

  assign z = (current_state == S0) && x;

endmodule

