module comparator_3bit (
    input [2:0] A,
    input [2:0] B,
    output A_greater,
    output A_equal,
    output A_less
);

wire [2:0] eq_bit;
wire [2:0] gt_bit;
wire [2:0] lt_bit;

// Equality bits (XNOR)
assign eq_bit[2] = (A[2] ~^ B[2]);
assign eq_bit[1] = (A[1] ~^ B[1]);
assign eq_bit[0] = (A[0] ~^ B[0]);

// Greater than bits (A > B)
assign gt_bit[2] = (A[2] & ~B[2]);
assign gt_bit[1] = (A[1] & ~B[1]);
assign gt_bit[0] = (A[0] & ~B[0]);

// Less than bits (A < B)
assign lt_bit[2] = (~A[2] & B[2]);
assign lt_bit[1] = (~A[1] & B[1]);
assign lt_bit[0] = (~A[0] & B[0]);

// Overall comparisons
assign A_greater = gt_bit[2] | (eq_bit[2] & gt_bit[1]) | (eq_bit[2] & eq_bit[1] & gt_bit[0]);
assign A_equal  = eq_bit[2] & eq_bit[1] & eq_bit[0];
assign A_less   = lt_bit[2] | (eq_bit[2] & lt_bit[1]) | (eq_bit[2] & eq_bit[1] & lt_bit[0]);

endmodule

