module synchronizer(
	input 				clk_a	, 
	input 				clk_b	,   
	input 				arstn	,
	input		[3:0]	data_in	,
	input               data_en ,

	output reg  [3:0] 	dataout
);

	// Signals in clk_a domain
	reg [3:0] data_reg;

	// Synchronize data_en to clk_a domain
	always @(posedge clk_a or negedge arstn) begin
		if (!arstn) begin
			data_reg <= 4'b0;
		end else begin
			data_reg <= data_in;
		end
	end

	// Synchronize data_en to clk_b domain
	reg sync_en_a, sync_en_b;
	always @(posedge clk_b or negedge brstn) begin
		if (!brstn) begin
			sync_en_a <= 1'b0;
			sync_en_b <= 1'b0;
		end else begin
			sync_en_a <= data_en;
			sync_en_b <= sync_en_a;
		end
	end

	// Update dataout in clk_b domain
	always @(posedge clk_b or negedge brstn) begin
		if (!brstn) begin
			dataout <= 4'b0;
		end else begin
			if (sync_en_b) begin
				dataout <= data_reg;
			end
		end
	end

endmodule

module fsm(IN,MATCH,CLK,RST);
input IN,CLK,RST;
output reg MATCH;

// Define states
localparam S0 = 3'd0,
           S1 = 3'd1,
           S2 = 3'd2,
           S3 = 3'd3,
           S4 = 3'd4;

reg [2:0] current_state, next_state;

// State transition and reset logic
always @(posedge CLK or posedge RST) begin
    if (RST) begin
        current_state <= S0;
    end else begin
        current_state <= next_state;
    end
end

// Next state logic based on current state and IN
always @(*) begin
    case (current_state)
        S0: next_state = IN ? S1 : S0;
        S1: next_state = IN ? S1 : S2;
        S2: next_state = IN ? S1 : S3;
        S3: next_state = IN ? S4 : S0;
        S4: next_state = IN ? S1 : S2;
        default: next_state = S0;
    endcase
end

// Output logic: MATCH is high only in state S4
always @(posedge CLK or posedge RST) begin
    if (RST) begin
        MATCH <= 1'b0;
    end else begin
        MATCH <= (current_state == S4);
    end
end

endmodule

